        if container is not None:
            try:
                container.remove(force=True)
            except docker.errors.APIError as e:
                logging.exception("Failed to stop challenge container")
                return JsonResponse({"message": "Failed to stop challenge", "status": "500"}, status=500)

        # Only mark stopped once the container is really gone
        user_chal.is_live = False
        user_chal.save()
        return JsonResponse({"message": "success", "status": "200"})
