```python
def lab3():
    import hmac, hashlib, json, base64, os
    from flask import request, render_template, make_response
    from datetime import datetime, timedelta
    SECRET_KEY = b"super-secret-key-change-in-production"

    if request.method == "GET":
        try:
            cookie_val = request.cookies.get("session_id")
            if cookie_val and "." in cookie_val:
                session_id, signature = cookie_val.rsplit(".", 1)
                expected_sig = hmac.new(SECRET_KEY, session_id.encode(), hashlib.sha256).hexdigest()
                if hmac.compare_digest(signature, expected_sig):
                    session_info = json.loads(base64.b64decode(session_id).decode())
                    if session_info.get("valid_until") and datetime.fromisoformat(session_info["valid_until"]) > datetime.now():
                        return render_template("lab3.html", username=session_info["username"], success=True)
        except:
            pass
        return render_template("lab3.html")

    elif request.method == "POST":
        username = request.form.get("username")
        password = request.form.get("password")
        if username in USERS and USERS[username]["password"] == hashlib.sha256(password.encode()).hexdigest():
            session_data = {
                "username": username,
                "role": USERS[username]["role"],
                "valid_until": (datetime.now() + timedelta(hours=1)).isoformat(),
            }
            session_id = base64.b64encode(json.dumps(session_data).encode()).decode()
            signature = hmac.new(SECRET_KEY, session_id.encode(), hashlib.sha256).hexdigest()
            response = make_response(render_template("lab3.html", success=True, username=username))
            response.set_cookie("session_id", f"{session_id}.{signature}", httponly=True, secure=True)
            return response
        return render_template("lab3.html", failure=True)
