def lab3():
    import hmac, hashlib, json, base64
    from flask import request, render_template, make_response
    from datetime import datetime, timedelta
    SECRET = b"secret"
    if request.method == "GET":
        val = request.cookies.get("session_id")
        if val and "." in val:
            data, sig = val.rsplit(".", 1)
            if hmac.compare_digest(sig, hmac.new(SECRET, data.encode(), hashlib.sha256).hexdigest()):
                info = json.loads(base64.b64decode(data).decode())
                if datetime.fromisoformat(info["valid_until"]) > datetime.now():
                    return render_template("lab3.html", username=info["username"], success=True)
        return render_template("lab3.html")
    elif request.method == "POST":
        user = request.form.get("username")
        pw = hashlib.sha256(request.form.get("password", "").encode()).hexdigest()
        if user in USERS and USERS[user]["password"] == pw:
            data = base64.b64encode(json.dumps({"username": user, "valid_until": (datetime.now() + timedelta(hours=1)).isoformat()}).encode()).decode()
            sig = hmac.new(SECRET, data.encode(), hashlib.sha256).hexdigest()
            res = make_response(render_template("lab3.html", success=True, username=user))
            res.set_cookie("session_id", f"{data}.{sig}", httponly=True, secure=True)
            return res
        return render_template("lab3.html", failure=True)
